// Reference entrance: central facility first, roads expand outward, equipment then copy.
(()=>{
const hero=document.querySelector('.network-hero-reference');if(!hero)return;
const reduced=matchMedia('(prefers-reduced-motion: reduce)'),pause=hero.querySelector('.network-hero-pause'),stage=hero.querySelector('.network-scene-stage'),paths=new Map([...hero.querySelectorAll('path[id^="hero-road-"]')].map(path=>[path.id,{path,length:path.getTotalLength()}]));
const vehicles=[...hero.querySelectorAll('.hero-network-vehicle')].map(el=>({el,route:paths.get(el.dataset.route),speed:Number(el.dataset.speed),offset:Number(el.dataset.offset),reverse:el.dataset.reverse==='true'}));
hero.classList.add('hero-intro-pending');
let visible=false,paused=false,frame=0,last=0,elapsed=0;
function draw(){for(const v of vehicles){const position=(v.offset*v.route.length+elapsed*v.speed)%v.route.length,distance=v.reverse?v.route.length-position:position,p=v.route.path.getPointAtLength(distance),q=v.route.path.getPointAtLength(Math.min(v.route.length,distance+.6)),angle=Math.atan2(q.y-p.y,q.x-p.x),lane=v.reverse?-10:10;v.el.style.transform=`translate(${p.x-Math.sin(angle)*lane}px,${p.y+Math.cos(angle)*lane}px) rotate(${angle*180/Math.PI+(v.reverse?270:90)}deg)`;}}
function running(){return visible&&!paused&&!reduced.matches&&!document.hidden;}
function tick(time){frame=0;if(!running())return;const dt=last?Math.min(50,time-last):16;last=time;elapsed+=dt/1000;draw();frame=requestAnimationFrame(tick);}
function sync(){last=0;hero.classList.toggle('hero-paused',paused||reduced.matches||!visible||document.hidden);if(running()&&!frame)frame=requestAnimationFrame(tick);else if(!running()&&frame){cancelAnimationFrame(frame);frame=0;}pause.textContent=paused?'▷':'Ⅱ';pause.setAttribute('aria-pressed',String(paused));pause.setAttribute('aria-label',paused?'Play hero animation':'Pause hero animation');}
function enter(){hero.classList.remove('hero-intro-pending');if(reduced.matches)return;const easing='cubic-bezier(.16,1,.3,1)';stage.animate([{opacity:0,transform:'scale(.62)'},{opacity:1,transform:'scale(1)'}],{duration:1750,easing,fill:'backwards'});const groups=[['.hero-road-centre',40],['.network-hero-centre',100],['.hero-road-left',250],['.hero-road-right,.hero-road-upper',420],['.hero-road-exit',500],['.network-hero-facility',430],['.network-hero-machinery',580],['.network-industrial-copy,.network-technology-copy,.network-products-copy',780],['.hero-network-vehicle,.hero-fluid-flow,.network-hero-pause',1000]];for(const [selector,delay] of groups)hero.querySelectorAll(selector).forEach(el=>el.animate([{opacity:0,translate:'0 14px'},{opacity:1,translate:'0 0'}],{duration:850,delay,easing,fill:'backwards'}));}
pause.addEventListener('click',()=>{paused=!paused;sync()});new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;sync()},{threshold:.01}).observe(hero);document.addEventListener('visibilitychange',sync);reduced.addEventListener('change',sync);hero.querySelectorAll('[data-hero-filter]').forEach(button=>button.addEventListener('click',()=>window.openCatalog(button.dataset.heroFilter)));
draw();const images=[...hero.querySelectorAll('img')];Promise.all(images.map(img=>img.complete?Promise.resolve():new Promise(resolve=>{img.addEventListener('load',resolve,{once:true});img.addEventListener('error',resolve,{once:true});}))).then(()=>document.fonts.ready).then(enter);
})();
